package main
import("compress/gzip";"crypto/sha256";"encoding/json";"fmt";"io";"os";"path/filepath";"reflect";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/pipeline")
func must(e error){if e!=nil{panic(e)}}
func read(p string)[]byte{b,e:=os.ReadFile(p);if e==nil{return b};f,e:=os.Open(p+".gz");must(e);defer f.Close();z,e:=gzip.NewReader(f);must(e);defer z.Close();b,e=io.ReadAll(z);must(e);return b}
func normalized(v any)any{b,e:=json.Marshal(v);must(e);var a any;must(json.Unmarshal(b,&a));return a}
func main(){root:=os.Args[1];for _,goal:=range []string{"speed","size"}{r:=filepath.Join(root,goal);var s pipeline.MemoryHostArenaAppendSelection;must(json.Unmarshal(read(filepath.Join(r,"selection.json")),&s));var profile hir.MemoryHostLoopProfileRun;must(json.Unmarshal(read(filepath.Join(r,"source-profile.json")),&profile));if s.Schema!="minz.memory-host-arena-append-selection/v1"||s.Options.Goal!=goal||s.Options.MaxSites!=2||len(s.Candidates)!=4||!reflect.DeepEqual(s.Profile,&profile)||!reflect.DeepEqual(s.Association.Profile,&profile){panic("profile/selection")};if profile.CompletedCalls!=30||profile.FailedCalls!=0{panic("calls")};for _,expected:=range []struct{site hir.LoopSite;function,path string}{{s.SourceSites.Arena,"region_match","body/s1"},{s.SourceSites.Append,"intern_region","body/s5"}}{found:=false;for i,site:=range profile.Sites.Sites{if site.ID==expected.site.ID{if found||!reflect.DeepEqual(site,expected.site)||site.Function!=expected.function||site.HIRPath!=expected.path||profile.Counts[i].Entries==0{panic("source site")};found=true}};if !found{panic("missing source site")}};winner:=0;for index,name:=range []string{"original","arena","append","both"}{candidate:=s.Candidates[index];choices:=hir.MemoryHostArenaAppendChoices{ArenaPeel:index&1!=0,AppendHoist:index&2!=0};var saved pipeline.MemoryHostBaselineEvidence;must(json.Unmarshal(read(filepath.Join(r,name,"factory-baseline.json")),&saved));if candidate.Choices!=choices||!reflect.DeepEqual(normalized(candidate.Evidence),normalized(saved)){panic("candidate binding")};p:=candidate.PrecompileProof;if p==nil||p.Schema!="minz.exact-memory-host-arena-append-precompile/v1"||p.Function!="region_match+intern_region"||p.Choices!=choices||!reflect.DeepEqual(p.SourceSites,s.SourceSites)||!reflect.DeepEqual(p.OriginalCompatibility,s.Candidates[0].Evidence.Compatibility)||!reflect.DeepEqual(p.ActualCompatibility,candidate.Evidence.Compatibility)||!reflect.DeepEqual(p.OriginalFunctions,s.Candidates[0].Evidence.FunctionSites)||!reflect.DeepEqual(p.ActualFunctions,candidate.Evidence.FunctionSites){panic("typed preproof")};for _,expected:=range []struct{site hir.LoopSite;path string}{{s.SourceSites.Arena,"body/s1"},{s.SourceSites.Append,"body/s5"}}{path:=expected.path;if expected.site.ID==s.SourceSites.Arena.ID&&choices.ArenaPeel{path="body/s4"};if expected.site.ID==s.SourceSites.Append.ID&&choices.AppendHoist{path="body/s7"};found:=false;for _,site:=range p.ActualSites.Sites{if site.ID==expected.site.ID{if found||site.Function!=expected.site.Function||site.Kind!=expected.site.Kind||site.HIRPath!=path||!reflect.DeepEqual(site.Origin,expected.site.Origin){panic("actual site")};found=true}};if !found{panic("missing actual site")}};a,b:=s.Candidates[winner].Evidence.Target,candidate.Evidence.Target;if goal=="speed"&&b.TotalTStates<a.TotalTStates||goal=="size"&&len(b.Binary)<len(a.Binary){winner=index}};if winner!=s.Selected{panic("objective")};b,e:=json.Marshal(s);must(e);p,e:=json.Marshal(profile);must(e);fmt.Printf("PASS %s typedSelectionSHA%x typedProfileSHA%x fourcandidatebaseline/preproof/twoSourceSites/actualpaths selected%d\n",goal,sha256.Sum256(b),sha256.Sum256(p),winner)}}
